  resources: EmbeddedAttemptSessionResources;
  onSessionYieldReady: (input: {
    abortActiveSession: SessionSettleTracker["abortActiveSession"];
    activeSession: AgentSession;
  }) => void;
}) {
  const { attempt, resources, runAbortSignal, sessionLock, toolBase } = input;
  const {
    agentCoreThinkingLevel,
    effectiveCwd,
    effectiveFsWorkspaceOnly,
    effectiveWorkspace,
    getCurrentAttemptPluginMetadataSnapshot,
    getProviderRuntimeHandle,
    prepStages,
    providerThinkingLevel,
    sandbox,
    sandboxSessionKey,
    sessionAgentId,
  } = input.setup;
  const {
    catalogToolHookContext,
    deferredDirectoryToolsCallable,
    effectiveTools,
    toolSearchRunPlan,
  } = input.toolCatalog;
  const { clientTools, uncompactedEffectiveTools } = input.bundleTools;
  const {
    codeModeControlsEnabledForRun,
    computerContextEpoch,
    localModelLeanEnabled,
    replaySafetyOptions,
    toolSearchCatalogRef,
    toolSearchRuntimeConfig,
  } = toolBase;
  const { systemPromptReport, systemPromptText } = input.systemPrompt;
  const effectiveToolCount = effectiveTools.length;
  const sessionPreparation = {
    attempt,
    assertCurrent: () => {
      runAbortSignal.throwIfAborted();
      sessionLock.ownedTranscriptWriteContext.assertCommitAllowed?.();
      sessionLock.ownedTranscriptWriteContext.initialWriter?.assertActive();
    },
    ...(input.activeContextEngine ? { activeContextEngine: input.activeContextEngine } : {}),
    agentDir: input.agentDir,
    effectiveCwd,
    effectiveWorkspace,
    sessionAgentId,
  };
  const preparedSessionManager = await measureEmbeddedAgentPreparation(
    "attempt.history",
    () =>
      prepareEmbeddedAttemptSessionManager({
        ...sessionPreparation,
        sessionTarget: sessionLock.ownedTranscriptWriteContext.sessionTarget,
        runAbortSignal,
        onSessionManagerCreated: (manager) => {
          resources.sessionManager = manager;
        },
        replayAllowedToolNames: toolSearchRunPlan.replayAllowedToolNames,
        resolveActiveContextEnginePluginId: input.resolveActiveContextEnginePluginId,
        withOwnedTranscriptWrite: sessionLock.withOwnedTranscriptWrite,
      }),
    { config: attempt.config },
  );
  const { isOpenAIResponsesApi, preparedUserTurnMessage, sessionManager, transcriptPolicy } =
    preparedSessionManager;
  if (codeModeControlsEnabledForRun && toolSearchCatalogRef) {
    bindCodeModeSessionStore(
      toolSearchCatalogRef,
      sessionManager,
      sessionLock.withOwnedTranscriptWrite,
    );
  }
  const promptStateLease = retainEmbeddedSessionPromptState(attempt.sessionId);
  resources.promptStateLease = promptStateLease;
  const sessionPromptState = promptStateLease.state;
  const usesSystemPromptSeries =
    !input.isRawModelRun && attempt.operation !== "settled-tool-finalization";
  const promptRouteKey = buildSystemPromptRouteKey({
    provider: attempt.provider,
    model: attempt.modelId,
    api: attempt.model.api,
    baseUrl: attempt.model.baseUrl,
    inHistorySystemUpdates: transcriptPolicy.inHistorySystemUpdates === true,
    // Personal bootstrap follows the session's selected human, not only the session ID.
    personalProfile: attempt.bootstrapUserProfileId,
  });
  // Retire old overrides before new carriers without checkpointing unadmitted notices.
  const retireSystemPromptUpdates = () =>
    sessionLock.withOwnedTranscriptWrite(() =>
      withSessionManagerAppend(sessionManager, async () => {
        runAbortSignal.throwIfAborted();
        await retireSessionSystemPrompt(sessionPromptState, promptRouteKey, (customType, data) =>
          sessionManager.appendCustomEntryAsync(customType, data),
        );
      }),
    );
  if (
    usesSystemPromptSeries &&
    beginSessionSystemPrompt({
      state: sessionPromptState,
      routeKey: promptRouteKey,
      enabled: transcriptPolicy.inHistorySystemUpdates === true,
      getEntries: () => sessionManager.getBranch(),
    })
  ) {
    await retireSystemPromptUpdates();
  }
  let freshSystemPrompt = systemPromptText;
  let projectedSystemPrompt: string | undefined;
  const prepareSystemPromptUpdate =
    usesSystemPromptSeries && transcriptPolicy.inHistorySystemUpdates
      ? async (systemPrompt: string, freshlyRendered = false) => {
          if (freshlyRendered || systemPrompt !== projectedSystemPrompt) {
            freshSystemPrompt = systemPrompt;
          }
          const prepared = prepareSessionSystemPrompt({
            state: sessionPromptState,
            routeKey: promptRouteKey,
            systemPrompt: freshSystemPrompt,
            entries: sessionManager.getBranch(),
            historyBoundaryCount: sessionManager.getBoundaryCount(),
          });
          // Keep an attempt's restart visible through subsequent continuation preparations.
          if (prepared.restart || state.systemPromptSeries === undefined) {
            state.systemPromptSeries = prepared.seriesStatus;
          }
          let restartRecorded = false;
          if (prepared.restart && resources.session) {
            await retireSystemPromptUpdates();
            restartRecorded = true;
            resources.session.agent.state.messages = resources.session.messages.filter(
              (message) => getOpenClawSystemUpdateKind(message) !== "prompt-update",
            );
          }
          projectedSystemPrompt = prepared.systemPrompt;
          return { ...prepared, commit: () => prepared.commit(restartRecorded) };
        }
      : undefined;
  resources.getUserTranscriptContexts =
    preparedSessionManager.userMessageBoundary.getUserTranscriptContexts;

  // Every turn of the session sends the pinned tool definitions, on any route. A tool
  // policy change starts a new pin, so configured removals leave the provider request.
  const toolPolicyDigest = sha256Hex(
    stableStringify([
      attempt.config?.tools,
      attempt.config?.agents?.entries?.[sessionAgentId]?.tools,
      attempt.config?.plugins,
      attempt.config?.desktop,
    ]),
  );
  const pinTools = usesSystemPromptSeries
    ? (tools: AnyAgentTool[]) => {
        const pending = sessionPromptState.pendingToolSurface;
        const pinned = prepareSessionToolSurface({
          state: sessionPromptState,
          routeKey: promptRouteKey,
          toolPolicy: toolPolicyDigest,
          entries: sessionManager.getBranch(),
          historyBoundaryCount: sessionManager.getBoundaryCount(),
          tools,
        });
        if (sessionPromptState.pendingToolSurface !== pending) {
          declarePromptToolPin(attempt);
        }
        return pinned;
      }
    : undefined;
  const state: EmbeddedAttemptSessionRuntimeState = {
    currentTurnImageFailureCount: 0,
    prePromptMessageCount: 0,
    promptCache: undefined,
    systemPromptText,
  };
  const preparedAgentSession = await withOwnedSessionTranscriptWrites(
    sessionLock.ownedTranscriptWriteContext,
    async () =>
      measureEmbeddedAgentPreparation(
        "attempt.actor",
        () =>
          prepareEmbeddedAttemptAgentSession({
            ...sessionPreparation,
            ...(input.activeContextEngine
              ? { activeContextEngineInfo: input.activeContextEngine.info }
              : {}),
            agentCoreThinkingLevel,
            clientToolPreparation: {
              catalogToolHookContext,
              clientTools,
              codeModeControlsEnabledForRun,
              deferredDirectoryToolsCallable,
              effectiveTools,
              pinTools,
              replaySafetyOptions,
              sandboxSessionKey,
              sessionAgentId,
              toolSearchCatalogRef,
              toolSearchRuntimeConfig,
              uncompactedEffectiveTools,
              getToolAbortSignal: () => toolBase.toolAbortSignal,
            },
            getCurrentAttemptPluginMetadataSnapshot,
            initialSystemPrompt: state.systemPromptText,
            prepareSystemPromptUpdate,
            markStage: (stage) => prepStages.mark(stage),
            onSessionCreated: (session) => {
              resources.session = session;
            },
            onSystemPromptChanged: (nextSystemPrompt) => {
              state.systemPromptText = nextSystemPrompt;
            },
            runAbortSignal,
            transcriptLifecycle: sessionLock.transcriptLifecycle,
            sessionManager,
            prepareInitialUserTurnReplay: preparedSessionManager.prepareInitialUserTurnReplay,
          }),
        { config: attempt.config },
      ),
  );
  const { activeSession, setActiveSessionSystemPrompt, settingsManager } = preparedAgentSession;
  const recordCurrentTurnImageFailure = (count: number) => {
    state.currentTurnImageFailureCount = Math.max(state.currentTurnImageFailureCount, count);
  };
  await attempt.userTurnTranscriptRecorder?.waitForRuntimePersistence();
  const boundary = await measureEmbeddedAgentPreparation(
    "attempt.history-boundary",
    () =>
      sessionLock.withOwnedTranscriptWrite(() =>
        prepareEmbeddedAttemptSessionBoundary({
          abortSignal: runAbortSignal,
          activeSession,
          appendOnlyRuntimeContext: transcriptPolicy.appendOnlyRuntimeContext,
          inHistorySystemUpdates: transcriptPolicy.inHistorySystemUpdates,
          attempt,
          ...preparedSessionManager.userMessageBoundary,
          isRawModelRun: input.isRawModelRun,
          sessionManager,
          setActiveSessionSystemPrompt,
        }),
      ),
    { config: attempt.config },
  );
  state.prePromptMessageCount = activeSession.messages.length;

  // Session-owned projections survive attempt teardown so already-sent tool results
  // cannot rewrite the provider prompt-cache tail between turns (#99495).
  const toolResultPromptProjectionState = sessionPromptState.toolResults;
  if (!input.isRawModelRun) {
    restoreCacheTtlToolResultProjections(
      toolResultPromptProjectionState,
      sessionManager.getToolResultProjectionEntries(),
    );
  }
  const settleTracker = createEmbeddedAttemptSessionSettleTracker(activeSession);
  input.externalAbortController.setActiveSessionAbort(settleTracker.abortActiveSession);
  resources.buildAbortSettlePromise = settleTracker.buildAbortSettlePromise;
  input.onSessionYieldReady({
    abortActiveSession: settleTracker.abortActiveSession,
    activeSession,
  });

  // Guard hooks execute during prompt submission, after transport preparation.
  const contextGuards = installEmbeddedAttemptContextGuards({
    ...sessionPreparation,
    activeSession,
    computerContextEpoch,
    dropThinkingBlocksForEstimate: transcriptPolicy.dropThinkingBlocks,
    effectiveFsWorkspaceOnly,
    getPrePromptMessageCount: () => state.prePromptMessageCount,
    getPromptCache: () => state.promptCache,
    onCurrentTurnImageFailure: recordCurrentTurnImageFailure,
    getPromptCacheRetention: () => transport.effectivePromptCacheRetention,
    getCompactionReplayEnabled: () => transport.compactionReplayEnabled,
    getServerToolClearingEnabled: () => transport.serverToolClearingEnabled,
    toolResultPromptProjectionState,
    getSystemPrompt: () => state.systemPromptText,
    isOpenAIResponsesApi,
    repairToolUseResultPairing: transcriptPolicy.repairToolUseResultPairing,
    sessionManager,
    settingsManager,
    sandbox,
  });
  resources.removeToolResultContextGuard = contextGuards.remove;

  const traceContext = {
    env: process.env,
    runId: attempt.runId,
    sessionId: activeSession.sessionId,
    sessionKey: attempt.sessionKey,
    provider: attempt.provider,
    modelId: attempt.modelId,
    modelApi: attempt.model.api,
    workspaceDir: attempt.workspaceDir,
  };
  const cacheTrace = createCacheTrace({ cfg: attempt.config, ...traceContext });
  const anthropicPayloadLogger = createAnthropicPayloadLogger(traceContext);
  let trajectoryRecorder: Awaited<ReturnType<typeof createTrajectoryRuntimeRecorder>> = null;
  {
    const clientToolCount = preparedAgentSession.clientToolDefs.length;
    const candidate = sessionLock.ownedTranscriptWriteContext?.sessionTarget;
    const sessionKey = candidate?.sessionKey;
    const assertCommitAllowed = sessionLock.ownedTranscriptWriteContext?.assertCommitAllowed;
    const initialWriter = sessionLock.ownedTranscriptWriteContext?.initialWriter;
    // Reuse only the lock owner's descriptive key; recorder persistence retains its own authority.
    const retained =
      candidate &&
      sessionKey &&
      assertCommitAllowed &&
      candidate.agentId === sessionAgentId &&
      candidate.sessionId === activeSession.sessionId &&
      sessionKey === attempt.sessionKey &&
      candidate.storePath &&
      candidate.storePath === attempt.sessionTarget?.storePath
        ? {
            sessionKey,
            assertCurrent() {
              assertCommitAllowed();
              initialWriter?.assertActive();
            },
          }
        : undefined;
    retained?.assertCurrent();
    const trajectorySessionFile = retained
      ? retained.sessionKey
      : await resolveAttemptTrajectorySessionFile({
          agentId: sessionAgentId,
          config: attempt.config,
          sessionFile: attempt.sessionFile,
          sessionId: activeSession.sessionId,
          sessionKey: attempt.sessionKey,
          sessionTarget: attempt.sessionTarget,
        });
    if (!attempt.disableTrajectory && attempt.sessionPersistence !== "detached") {
      const assertActive = resolveAdmittedRunActiveAssertion(
        attempt.admittedRunContext,
        attempt.abortSignal,
      );
      if (!assertActive) {
        throw new Error("trajectory preparation requires an active admitted run");
      }
      assertActive();
      retained?.assertCurrent();
      const { sessionTarget } = projectTrajectorySessionTarget(attempt.sessionTarget);
      const recorder = await createTrajectoryRuntimeRecorder({
        cfg: attempt.config,
        env: process.env,
        runId: attempt.runId,
        sessionId: activeSession.sessionId,
        sessionKey: attempt.sessionKey,
        sessionFile: trajectorySessionFile,
        sessionTarget,
        provider: attempt.provider,
        modelId: attempt.modelId,
        modelApi: attempt.model.api,
        workspaceDir: attempt.workspaceDir,
      });
      assertActive();
      retained?.assertCurrent();
      recorder?.recordEvent("session.started", {
        trigger: attempt.trigger,
        sessionFile: attempt.sessionFile,
        workspaceDir: effectiveWorkspace,
        agentId: sessionAgentId,
        messageProvider: attempt.messageProvider,
        messageChannel: attempt.messageChannel,
        localModelLean: localModelLeanEnabled,
        toolCount: effectiveToolCount,
        clientToolCount,
      });
      const fastMode = typeof attempt.fastMode === "boolean" ? attempt.fastMode : undefined;
      recorder?.recordEvent(
        "trace.metadata",
        buildTrajectoryRunMetadata({
          env: process.env,
          config: attempt.config,
          ...(attempt.preparedModelRuntime?.metadataSnapshot
            ? { pluginMetadataSnapshot: attempt.preparedModelRuntime.metadataSnapshot }
            : {}),
          workspaceDir: effectiveWorkspace,
          sessionFile: attempt.sessionFile,
          sessionKey: attempt.sessionKey,
          agentId: sessionAgentId,
          trigger: attempt.trigger,
          messageProvider: attempt.messageProvider,
          messageChannel: attempt.messageChannel,
          provider: attempt.provider,
          modelId: attempt.modelId,
          modelApi: attempt.model.api,
          timeoutMs: attempt.timeoutMs,
          fastMode,
          thinkLevel: attempt.thinkLevel,
          reasoningLevel: attempt.reasoningLevel,
          toolResultFormat: attempt.toolResultFormat,
          disableTools: attempt.disableTools,
          toolsAllow: attempt.toolsAllow,
          skillsSnapshot: attempt.skillsSnapshot,
          systemPromptReport,
        }),
      );
      trajectoryRecorder = recorder;
    }
  }
  resources.trajectoryRecorder = trajectoryRecorder;

  const transport = await prepareEmbeddedAttemptTransport({
    attempt,
    contextEngineInfo: input.activeContextEngine?.info,
    assertCronRootCurrent: sessionLock.assertCronRootCurrent,
    session: activeSession,
    settingsManager,
    providerThinkingLevel,
    sessionAgentId,
    workspaceDir: effectiveWorkspace,
    workspaceOnly: effectiveFsWorkspaceOnly,
    agentDir: input.agentDir,
    abortSignal: runAbortSignal,
    getProviderRuntimeHandle,
    onCurrentTurnImageFailure: recordCurrentTurnImageFailure,
    sandboxSessionKey,
    ...(sandbox !== undefined ? { sandbox } : {}),
    codeModeControlsEnabled: codeModeControlsEnabledForRun,
    providerPromptState: {
      state: getProviderPromptState(attempt.runId),
      effectiveContextTokenBudget: Math.max(
        1,
        Math.floor(
          attempt.contextTokenBudget ?? attempt.model.contextWindow ?? DEFAULT_CONTEXT_TOKENS,
        ),
      ),
      ...(trajectoryRecorder ? { recordEvent: trajectoryRecorder.recordEvent } : {}),
    },
  });

  return {
    agentSession: preparedAgentSession,
    anthropicPayloadLogger,
    boundary,
    cacheTrace,
    contextGuards,
    isOpenAIResponsesApi,
    preparedUserTurnMessage,
    prepareSystemPromptUpdate,
    sessionManager,
    sessionPromptState,
    settleTracker,
    state,
    toolResultPromptProjectionState,
    trajectoryRecorder,
    transcriptPolicy,
    transport,
  };
}

import { formatErrorMessage, toErrorObject } from "../../../infra/errors.js";
import { createPendingPromiseTracker } from "../../../shared/pending-promises.js";
import type { createTrajectoryRuntimeRecorder } from "../../../trajectory/runtime.js";
import { projectAgentRunAttemptTerminal } from "../../agent-run-terminal-outcome.js";
import { buildExecAutoReviewTranscript } from "../../exec-auto-review-transcript.js";
import { recordAgentCleanupFailure } from "../../run-cleanup-timeout.js";
import type { guardSessionManager } from "../../session-tool-result-guard-wrapper.js";
import type { AgentSession } from "../../sessions/index.js";
import { clearToolSearchCatalog, type ToolSearchCatalogRef } from "../../tool-search.js";
import { log } from "../logger.js";
import type { retainEmbeddedSessionPromptState } from "../session-prompt-state.js";
import { flushPendingToolResultsAfterIdle } from "../wait-for-idle-before-flush.js";
import type { UserTranscriptContext } from "./attempt-llm-boundary.types.js";
import type { EmitDiagnosticRunCompleted } from "./attempt-setup.js";
import { cleanupEmbeddedAttemptResources } from "./attempt-subscription-cleanup.js";
import { flushEmbeddedAttemptTrajectoryRecorder } from "./attempt-trajectory-flush.js";
import type { createEmbeddedAttemptTranscriptLifecycle } from "./attempt-transcript-lifecycle.js";
import type { EmbeddedAttemptDeferredLifecycleOwner } from "./deferred-lifecycle-owner.js";
import type { EmbeddedAttemptExecutionState, EmbeddedRunAttemptParams } from "./types.js";

export function createEmbeddedAttemptSessionSettleTracker(
  activeSession: Pick<AgentSession, "abort">,
) {
  const inFlight = new Set<Promise<void>>();
  let abortCleanupFailed = false;
  const recordAbortCleanupFailure = () => {
    if (abortCleanupFailed) {
      recordAgentCleanupFailure();
    }
  };
  const trackSettlePromise = createPendingPromiseTracker(inFlight);

  return {
    abortActiveSession: (reason?: unknown) =>
      trackSettlePromise(
        Promise.resolve(activeSession.abort(reason)).catch((error: unknown) => {
          abortCleanupFailed = true;
          throw error;
        }),
      ),
    buildAbortSettlePromise: () => {
      // Abort callbacks can run outside the caller's async context. Record their
      // retained failure from the cleanup owner that joins settlement.
      recordAbortCleanupFailure();
      return inFlight.size === 0
        ? null
        : Promise.allSettled(inFlight).then(recordAbortCleanupFailure);
    },
    trackPromptSettlePromise: trackSettlePromise,
  };
}

type AttemptTranscriptLifecycle = ReturnType<typeof createEmbeddedAttemptTranscriptLifecycle>;
type TrajectoryRecorder = Awaited<ReturnType<typeof createTrajectoryRuntimeRecorder>>;
type DisposableRuntime = { dispose(): Promise<void> | void };

export type EmbeddedAttemptSessionResources = {
  promptStateLease?: ReturnType<typeof retainEmbeddedSessionPromptState>;
  session?: AgentSession;
  getUserTranscriptContexts?: () => readonly UserTranscriptContext[] | undefined;
  sessionManager?: ReturnType<typeof guardSessionManager>;
  removeToolResultContextGuard?: () => void;
  trajectoryRecorder: TrajectoryRecorder | null;
  buildAbortSettlePromise: () => Promise<void> | null;
};

/** Keep retained review callbacks outside the attempt's tool-execution closure scope. */
export function createEmbeddedAttemptSessionResources(signal: AbortSignal) {
  let resources: EmbeddedAttemptSessionResources = {
    trajectoryRecorder: null,
    buildAbortSettlePromise: () => null,
  };
  return {
    get resources() {
      return resources;
    },
    reviewTranscript: () => {
      if (!resources.session || signal.aborted) {
        return undefined;
      }
      return buildExecAutoReviewTranscript({
        messages: resources.session.messages,
        userTurnOrigins: new Map(
          resources
            .getUserTranscriptContexts?.()
            ?.map(({ runtimeMessage, transcriptMessage }) => [runtimeMessage, transcriptMessage]),
        ),
      });
    },
    takeForCleanup: () => {
      const released = resources;
      resources = { trajectoryRecorder: null, buildAbortSettlePromise: () => null };
      return released;
    },
  };
}

type CleanupEmbeddedAttemptSessionInput = EmbeddedAttemptSessionResources & {
  attempt: Pick<EmbeddedRunAttemptParams, "runId" | "sessionId" | "abortSignal">;
  transcriptLifecycle: Pick<AttemptTranscriptLifecycle, "beginCleanup" | "dispose">;
  bundleMcpRuntime?: DisposableRuntime;
  bundleLspRuntime?: DisposableRuntime;
  toolSearchCatalogRef?: ToolSearchCatalogRef;
  trajectoryEndRecorded: boolean;
  deferredLifecycleOwner?: EmbeddedAttemptDeferredLifecycleOwner;
  emitDiagnosticRunCompleted?: EmitDiagnosticRunCompleted;
  state: Pick<
    EmbeddedAttemptExecutionState,
    "terminal" | "beforeAgentRunBlockedBy" | "diagnosticFinalResponse"
  >;
};

export async function cleanupEmbeddedAttemptSessionPhase(
  input: CleanupEmbeddedAttemptSessionInput,
): Promise<void> {
  using _ = input.promptStateLease;
  const clearTranscriptRunCallbacks = input.sessionManager?.clearTranscriptRunCallbacks;
  const { attempt } = input;
  const initialState = projectAgentRunAttemptTerminal(input.state.terminal);
  if (input.trajectoryRecorder && !input.trajectoryEndRecorded) {
    const sessionEndData = {
      status: initialState.promptError
        ? "error"
        : initialState.aborted || initialState.timedOut
          ? "interrupted"
          : "cleanup",
      aborted: initialState.aborted,
      externalAbort: initialState.externalAbort,
      timedOut: initialState.timedOut,
      idleTimedOut: initialState.idleTimedOut,
      timedOutDuringCompaction: initialState.timedOutDuringCompaction,
      timedOutDuringToolExecution: initialState.timedOutDuringToolExecution,
      timedOutByRunBudget: initialState.timedOutByRunBudget,
      promptError: initialState.promptError
        ? formatErrorMessage(initialState.promptError)
        : undefined,
    };
    if (input.deferredLifecycleOwner) {
      input.deferredLifecycleOwner.recordSessionEnd(sessionEndData);
    } else {
      input.trajectoryRecorder.recordEvent("session.ended", sessionEndData);
    }
  }
  if (
    !input.deferredLifecycleOwner ||
    input.state.terminal.kind !== "ok" ||
    input.state.terminal.settlementWarning ||
    attempt.abortSignal?.aborted ||
    input.state.beforeAgentRunBlockedBy !== undefined
  ) {
    await flushEmbeddedAttemptTrajectoryRecorder({
      runId: attempt.runId,
      sessionId: attempt.sessionId,
      log,
      trajectoryRecorder: input.trajectoryRecorder,
    });
  }

  // Agent retries can report idle before retried tools finish; waiting before
  // the flush prevents synthetic missing-tool results (#8643). Teardown keeps
  // lock release ahead of runtime disposal so the next attempt can recover.
  let cleanupError: unknown;
  try {
    clearToolSearchCatalog({ catalogRef: input.toolSearchCatalogRef });
    await input.transcriptLifecycle.beginCleanup(clearTranscriptRunCallbacks);
    // Cancellation can arrive during trajectory flushing or the transcript drain.
    // Read it only after both waits before deciding whether to wait for idle.
    const cleanupState = projectAgentRunAttemptTerminal(input.state.terminal);
    const cleanupAborted =
      Boolean(attempt.abortSignal?.aborted) ||
      cleanupState.aborted ||
      cleanupState.timedOut ||
      cleanupState.idleTimedOut ||
      cleanupState.timedOutDuringCompaction;
    const cleanupAbortLike = cleanupAborted || initialState.cleanupYieldAborted;
    await cleanupEmbeddedAttemptResources({
      ...input,
      sessionManager: input.sessionManager,
      flushPendingToolResultsAfterIdle,
      // Aborted runs skip the idle wait so teardown cannot strand the lock.
      aborted: cleanupAbortLike,
      abortSignal: attempt.abortSignal,
      abortSettlePromise: cleanupAborted ? input.buildAbortSettlePromise() : null,
      runId: attempt.runId,
      sessionId: attempt.sessionId,
    });
  } catch (err) {
    recordAgentCleanupFailure();
    cleanupError = err;
  } finally {
    try {
      await input.transcriptLifecycle.dispose();
    } catch (err) {
      recordAgentCleanupFailure();
      cleanupError ??= err;
    }
  }

  const finalState = projectAgentRunAttemptTerminal(input.state.terminal);
  const beforeAgentRunBlocked = input.state.beforeAgentRunBlockedBy !== undefined;
  const diagnosticTerminalAborted =
    finalState.aborted || finalState.timedOut || finalState.idleTimedOut;
  input.emitDiagnosticRunCompleted?.(
    cleanupError
      ? "error"
      : beforeAgentRunBlocked
        ? "blocked"
        : finalState.promptError
          ? "error"
          : diagnosticTerminalAborted
            ? "aborted"
            : "completed",
    cleanupError ?? finalState.promptError,
    beforeAgentRunBlocked
      ? { blockedBy: input.state.beforeAgentRunBlockedBy }
      : input.state.diagnosticFinalResponse
        ? { finalResponse: input.state.diagnosticFinalResponse }
        : undefined,
  );

  if (cleanupError) {
    await Promise.reject(toErrorObject(cleanupError, "Non-Error rejection"));
  }
}

import { parseStrictPositiveInteger } from "@openclaw/normalization-core/number-coercion";
import { isFastTestRuntimeEnv } from "../../../infra/test-runtime-env.js";
import { recordAgentCleanupFailure, runAgentCleanupStep } from "../../run-cleanup-timeout.js";
import { log } from "../logger.js";
import type { flushPendingToolResultsAfterIdle } from "../wait-for-idle-before-flush.js";

// Invalid overrides retain the normal/test defaults; partial numeric parsing
// must not silently widen cleanup waits.
const EMBEDDED_ABORT_SETTLE_TIMEOUT_MS =
  parseStrictPositiveInteger(process.env.OPENCLAW_EMBEDDED_ABORT_SETTLE_TIMEOUT_MS) ??
  (isFastTestRuntimeEnv() ? 250 : 2_000);

type ToolResultFlushOptions = Parameters<typeof flushPendingToolResultsAfterIdle>[0];

export async function waitForEmbeddedAbortSettle(params: {
  promise: Promise<unknown> | null | undefined;
  runId: string;
  sessionId: string;
  reason?: "embedded" | "sessions_yield";
}): Promise<void> {
  if (!params.promise) {
    return;
  }

  await runAgentCleanupStep({
    runId: params.runId,
    sessionId: params.sessionId,
    step: `${params.reason ?? "embedded"}-abort-settle`,
    log,
    timeoutMs: EMBEDDED_ABORT_SETTLE_TIMEOUT_MS,
    cleanup: async () => {
      await params.promise;
    },
  });
}

/**
 * Tears down per-attempt resources after the transcript lifecycle has drained:
 * remove guards, settle aborted prompts, join cleanup writes, then dispose runtimes.
 */
export async function cleanupEmbeddedAttemptResources(params: {
  removeToolResultContextGuard?: () => void;
  flushPendingToolResultsAfterIdle: typeof flushPendingToolResultsAfterIdle;
  session?: { agent?: ToolResultFlushOptions["agent"]; dispose(): void };
  sessionManager: ToolResultFlushOptions["sessionManager"];
  bundleMcpRuntime?: { dispose(): Promise<void> | void };
  bundleLspRuntime?: { dispose(): Promise<void> | void };
  aborted?: boolean;
  abortSignal?: AbortSignal;
  abortSettlePromise?: Promise<unknown> | null;
  runId?: string;
  sessionId?: string;
}): Promise<void> {
  try {
    params.removeToolResultContextGuard?.();
  } catch {
    recordAgentCleanupFailure();
  }
  if (params.aborted && params.abortSettlePromise) {
    await waitForEmbeddedAbortSettle({
      promise: params.abortSettlePromise,
      runId: params.runId ?? "unknown",
      sessionId: params.sessionId ?? "unknown",
    });
  }
  try {
    await params.flushPendingToolResultsAfterIdle({
      agent: params.session?.agent,
      sessionManager: params.sessionManager,
      ...(params.aborted ? { timeoutMs: 0 } : {}),
      ...(params.abortSignal ? { abortSignal: params.abortSignal } : {}),
    });
  } catch {
    recordAgentCleanupFailure();
  }

  try {
    params.session?.dispose();
  } catch {
    recordAgentCleanupFailure();
  }
  for (const key of ["bundleMcpRuntime", "bundleLspRuntime"] as const) {
    try {
      await params[key]?.dispose();
    } catch {
      recordAgentCleanupFailure();
    }
  }
}

/** Serializes run-owned transcript callbacks and bounds teardown settlement. */
import { AsyncLocalStorage } from "node:async_hooks";
import { toErrorObject } from "../../../infra/errors.js";
import { runWithAsyncStore } from "../../../shared/async-store.js";
import { createDeferredCore } from "../../../shared/deferred.js";
import { settlesWithin } from "../../../shared/settle-within.js";
import { log } from "../logger.js";

const TRANSCRIPT_TEARDOWN_BUDGET_MS = 30_000;

type LifecycleOwner = {
  readonly attempt: symbol;
  readonly parent: LifecycleOwner | undefined;
  active: boolean;
  nestedTail: Promise<void>;
  pendingOperations: Set<Promise<void>>;
};

const lifecycleOwners = new AsyncLocalStorage<LifecycleOwner>();

export type EmbeddedAttemptTranscriptLifecycle = {
  withTranscriptWrite<T>(run: () => Promise<T> | T): Promise<T>;
  /** Retire callbacks after the actual drain, including when owner release fails. */
  beginCleanup(onDrained?: () => void): Promise<void>;
  dispose(): Promise<void>;
};

export function createEmbeddedAttemptTranscriptLifecycle(params: {
  runId?: string;
  sessionId?: string;
  /** Release retained owners after accepted descendants settle, even after a teardown timeout. */
  onDrained?: () => void | Promise<void>;
}): EmbeddedAttemptTranscriptLifecycle {
  let disposed = false;
  let lifecycle = Promise.resolve();
  let cleanupDrain: Promise<void> | undefined;
  let disposePromise: Promise<void> | undefined;
  let pendingWrites = 0;
  const attempt = Symbol("transcript-attempt");
  // Writes may enter another attempt's lifecycle before re-entering this one.
  const currentOwner = (): LifecycleOwner | undefined => {
    for (let owner = lifecycleOwners.getStore(); owner; owner = owner.parent) {
      if (owner.attempt === attempt) {
        return owner;
      }
    }
    return undefined;
  };

  const createLifecycleOwner = (): LifecycleOwner => ({
    attempt,
    parent: lifecycleOwners.getStore(),
    active: true,
    nestedTail: Promise.resolve(),
    pendingOperations: new Set(),
  });
  const drainLifecycleOwner = async (owner: LifecycleOwner): Promise<void> => {
    let firstError: Error | undefined;
    while (owner.pendingOperations.size > 0) {
      const pending = [...owner.pendingOperations];
      owner.pendingOperations.clear();
      const settled = await Promise.allSettled(pending);
      const rejected = settled.find((result) => result.status === "rejected");
      if (firstError === undefined && rejected?.status === "rejected") {
        firstError = toErrorObject(rejected.reason, "nested transcript write failed");
      }
    }
    if (firstError !== undefined) {
      throw firstError;
    }
  };
  const runLifecycleOwner = async <T>(
    owner: LifecycleOwner,
    run: () => Promise<T> | T,
  ): Promise<T> => {
    let value: T | undefined;
    let primaryError: Error | undefined;
    try {
      value = await runWithAsyncStore(lifecycleOwners, owner, async () => await run());
    } catch (error) {
      primaryError = toErrorObject(error, "transcript write failed");
    }
    let drainError: Error | undefined;
    try {
      await drainLifecycleOwner(owner);
    } catch (error) {
      drainError = toErrorObject(error, "nested transcript drain failed");
    } finally {
      owner.active = false;
    }
    if (
      primaryError !== undefined &&
      drainError !== undefined &&
      drainError !== primaryError &&
      primaryError.cause === undefined
    ) {
      try {
        primaryError.cause = drainError;
      } catch {
        // Frozen callback errors remain primary; drain failure is secondary.
      }
    }
    const failure = primaryError ?? drainError;
    if (failure !== undefined) {
      throw failure;
    }
    return value as T;
  };
  const serializeLifecycle = async <T>(run: () => Promise<T> | T): Promise<T> => {
    const inheritedOwner = currentOwner();
    if (inheritedOwner?.active) {
      const operation = inheritedOwner.nestedTail.then(
        async () => await runLifecycleOwner(createLifecycleOwner(), run),
      );
      inheritedOwner.nestedTail = operation.then(
        () => undefined,
        () => undefined,
      );
      const propagated = operation.then(() => undefined);
      void propagated.catch(() => {});
      inheritedOwner.pendingOperations.add(propagated);
      return await operation;
    }

    const previous = lifecycle;
    const { promise, resolve: release } = createDeferredCore();
    lifecycle = promise;
    await previous;
    const owner = createLifecycleOwner();
    try {
      return await runLifecycleOwner(owner, run);
    } finally {
      release();
    }
  };
  const settleWithinTeardownBudget = async (operation: Promise<void>): Promise<void> => {
    if (!(await settlesWithin(operation, TRANSCRIPT_TEARDOWN_BUDGET_MS))) {
      log.error(
        `transcript teardown budget expired: runId=${params.runId ?? "unknown"} ` +
          `sessionId=${params.sessionId ?? "unknown"} pendingWrites=${pendingWrites} ` +
          `timeoutMs=${TRANSCRIPT_TEARDOWN_BUDGET_MS}`,
      );
    }
  };
  const beginCleanup = async (onDrained?: () => void): Promise<void> => {
    if (currentOwner()?.active) {
      throw new Error("cannot start attempt cleanup inside a transcript write callback");
    }
    // Accepted descendants retain their owner until the drain settles, even when
    // the bounded teardown budget expires. Cleanup never disables the shared carrier.
    cleanupDrain ??= settleWithinTeardownBudget(
      serializeLifecycle(async () => {
        currentOwner()!.active = false;
        try {
          await params.onDrained?.();
        } finally {
          onDrained?.();
        }
      }),
    );
    await cleanupDrain;
  };

  return {
    withTranscriptWrite: (run) => {
      const activeDescendant = currentOwner()?.active === true;
      if ((cleanupDrain || disposed) && !activeDescendant) {
        const rejected = Promise.reject(
          new Error(
            disposed
              ? "attempt disposed before transcript write"
              : "attempt cleanup started before transcript write",
          ),
        );
        void rejected.catch(() => {});
        return rejected;
      }
      pendingWrites += 1;
      const operation = serializeLifecycle(run);
      void operation
        .finally(() => {
          pendingWrites -= 1;
        })
        .catch(() => {});
      return operation;
    },
    beginCleanup,
    dispose: async () => {
      if (currentOwner()?.active) {
        throw new Error("cannot dispose an attempt from inside a transcript write callback");
      }
      disposePromise ??= (async () => {
        await beginCleanup();
        disposed = true;
      })();
      await disposePromise;
    },
  };
}

import { isDeepStrictEqual } from "node:util";
import { asOptionalRecord } from "@openclaw/normalization-core/record-coerce";
import type { AgentMessage } from "../../../../packages/agent-core/src/types.js";
import {
  prepareForeignLiveSessionPendingInputEntries,
  readSessionSubmittedInput,
